    if(modifiedConfigItems[key]) {
        callback(modifiedConfigItems[key]);
        return;
    }
    request.post({
        "url": CLIENT_SERVICE_ADDR + "config/get",
        "body": JSON.stringify({
            "key": key
        })
    }, (err, resp, body) => {
        if(err || !body || body == "Failed" || body == "Unknown type") callback(null);
        else callback(body);
    });
